import {
  BarChart3,
  Briefcase,
  Building2,
  CalendarDays,
  FileBarChart2,
  FileText,
  Hand,
  LayoutDashboard,
  LogOut,
  MessageCircle,
  Settings,
  ShieldCheck,
  Users,
} from 'lucide-react';

export const ROLES = {
  EMPLOYEE: 'employee',
  MANAGER: 'manager',
  HR: 'hr_admin',
};

export const navSections = [
  {
    title: 'MAIN',
    items: [
      { label: 'Dashboard', icon: LayoutDashboard, path: '/dashboard', roles: [ROLES.EMPLOYEE, ROLES.MANAGER, ROLES.HR] },
      { label: 'Apply for Leave', icon: FileText, path: '/dashboard#apply-leave', section: 'apply-leave', roles: [ROLES.EMPLOYEE, ROLES.MANAGER, ROLES.HR] },
      { label: 'My Leave', icon: FileText, path: '/dashboard#my-leave', section: 'my-leave', roles: [ROLES.EMPLOYEE, ROLES.MANAGER, ROLES.HR] },
      { label: 'History', icon: FileBarChart2, path: '/dashboard#history', section: 'history', roles: [ROLES.EMPLOYEE, ROLES.MANAGER, ROLES.HR] },
      { label: 'Handover report', icon: Hand, path: '/dashboard#delegations', section: 'delegations', roles: [ROLES.EMPLOYEE, ROLES.MANAGER, ROLES.HR] },
      { label: 'Chat', icon: MessageCircle, path: '/dashboard#chat', section: 'chat', roles: [ROLES.EMPLOYEE, ROLES.MANAGER, ROLES.HR], badge: 'unread' },
    ],
  },
  {
    title: 'TEAM',
    items: [
      { label: 'Approvals', icon: ShieldCheck, path: '/dashboard#approvals', section: 'approvals', roles: [ROLES.MANAGER, ROLES.HR], badge: 'pendingApprovals' },
      { label: 'Team Calendar', icon: CalendarDays, path: '/dashboard#team-calendar', section: 'team-calendar', roles: [ROLES.MANAGER, ROLES.HR] },
      { label: 'Sales Reports', icon: BarChart3, path: '/dashboard#sales-reports', section: 'sales-reports', roles: [ROLES.EMPLOYEE, ROLES.MANAGER, ROLES.HR] },
    ],
  },
  {
    title: 'HR',
    items: [
      { label: 'HR Module', icon: Briefcase, path: '/dashboard#hr-module', section: 'hr-module', roles: [ROLES.HR] },
      { label: 'HR Verification', icon: ShieldCheck, path: '/dashboard#approvals', section: 'hr-verification', roles: [ROLES.HR] },
      { label: 'Users', icon: Users, path: '/dashboard#managed-users', section: 'users', roles: [ROLES.HR] },
      { label: 'Departments', icon: Building2, path: '/dashboard#departments', section: 'departments', roles: [ROLES.HR] },
    ],
  },
  {
    title: 'ACCOUNT',
    items: [
      { label: 'Edit profile', icon: Settings, path: '/dashboard#profile', section: 'profile', roles: [ROLES.EMPLOYEE, ROLES.MANAGER, ROLES.HR] },
      { label: 'Sign out', icon: LogOut, path: '/logout', action: 'logout', roles: [ROLES.EMPLOYEE, ROLES.MANAGER, ROLES.HR] },
    ],
  },
  {
    title: 'ADMINISTRATION',
    items: [
      { label: 'Apply for Leave', icon: FileText, path: '/dashboard#apply-leave', section: 'apply-leave', roles: [ROLES.HR], superAdminOnly: true },
      { label: 'Pending Leave Approvals', icon: ShieldCheck, path: '/dashboard#pending-leave-approvals', section: 'approvals', roles: [ROLES.HR], superAdminOnly: true, badge: 'pendingApprovals' },
      { label: 'Sales Reports', icon: BarChart3, path: '/dashboard#sales-reports', section: 'sales-reports', roles: [ROLES.HR], superAdminOnly: true },
      { label: 'Employee Directory', icon: Users, path: '/dashboard#managed-users', section: 'users', roles: [ROLES.HR], superAdminOnly: true },
    ],
  },
];

export const accessibleNavSections = (role, isSuperAdmin = false) => navSections
  .map((section) => ({ ...section, items: section.items.filter((item) => item.roles.includes(role) && (isSuperAdmin ? (item.superAdminOnly || item.label === 'Dashboard' || section.title === 'ACCOUNT') : !item.superAdminOnly)) }))
  .filter((section) => section.items.length > 0);
